    S(3, '도입', 'motivate', { scene_title: '먼 길을 떠나는 행렬', desc: '한양의 성문 앞, 긴 **행렬**이 길을 나서요. 맨 앞에는 임금의 **편지**를 담은 상자가 있고, 뒤로는 다른 나라 말을 할 줄 아는 사람과 **선물** 짐을 실은 말들이 따라가요.', question: '이 사람들은 어디로, 무엇을 하러 먼 길을 떠났을까요?', img: 'assets/photo/social/sasin_haengnyeol.jpg', tnote: TN('다른 나라와 사이좋게 지내려면 어떤 사람들이 필요할까요?', '다른 나라와 오가며 지내면 어떤 점이 좋을까요?', '「여행 가는 사람들」로 끝나는 경우 — 편지 상자와 선물 짐이 왜 필요한지로 하는 일 짐작하기', 4) }, ['t_l7_1']),
    S(4, '전개', 'concept', { fig: { k: 'chain', items: [{ emoji: '🏯', name: '조선' }, { emoji: '📜', name: '사신' }, { emoji: '📦', name: '명의 문물' }, { emoji: '🌱', name: '나라 발전' }] }, title: '큰 이웃 명과는 사이좋게', content: '조선 주변에는 **명**, **일본**, **여진** 등이 있었어요. 조선은 명과 대체로 **좋은 관계**를 이어 가며 **사신**을 보냈고, 명으로부터 필요한 **문물**을 받아들여 나라를 발전시키려 했어요.', tnote: TN('조선 주변에는 어떤 나라들이 있었나요?', '명과 사이좋게 지내면 조선에 어떤 점이 좋았을까요?', '「명이 커서 따랐다」로만 끝나는 경우 — 조선이 얻으려 한 것(문물·평화)을 함께 말하기', 5) }, ['t_l7_2', 'e_l7_1']),
    S(5, '전개', 'concept', { fig: { k: 'tools', items: [{ emoji: '🤝', name: '무역', kind: '일본·여진과 교류' }, { emoji: '⚓', name: '쓰시마섬', kind: '왜구 소굴 공격' }, { emoji: '🏔️', name: '4군', kind: '압록강 유역' }, { emoji: '🛡️', name: '6진', kind: '두만강 유역' }] }, title: '일본·여진과는 교류와 무력을 함께', content: '조선은 **일본**, **여진**과 **무역**으로 교류하면서, 국경을 넘어와 빼앗으면 **무력**도 썼어요. 세종 때에는 바다의 해적 **왜구**의 소굴인 **쓰시마섬**을 공격했고, 북쪽으로 여진을 몰아내 **4군**과 **6진**을 두어 영토를 넓혔어요.', tnote: TN('일본·여진과 무역을 하면서도 군대를 보낸 까닭은 무엇일까요?', '교과서 지도에서 4군과 6진은 어느 강 가까이에 있나요?', '「싸워서 이겼다」로만 끝나는 경우 — 달래는 길(무역)과 맞서는 길(무력)을 함께 쓴 까닭 찾기', 6) }, ['t_l7_2', 'q_l7_2']),
    S(6, '전개', 'concept', { fig: { k: 'chain', items: [{ emoji: '⚔️', name: '일본의 침략' }, { emoji: '😰', name: '큰 위기' }, { emoji: '⛵', name: '함께 맞섬' }, { emoji: '🌅', name: '이겨 냄' }] }, title: '일본의 침략 — 임진왜란', content: '조선이 세워지고 오랜 시간이 흐른 뒤, **일본**이 많은 군사로 쳐들어왔어요. 이 전쟁이 **임진왜란**이에요. 조선은 **조총**을 앞세운 일본군에 잇달아 졌지만, **이순신**이 이끄는 **수군**과 백성이 스스로 만든 군대 **의병**, **명군**의 도움으로 위기를 이겨 냈어요.', tnote: TN('전쟁 초기에 조선이 잇달아 진 까닭은 무엇일까요?', '임진왜란으로 조선은 어떤 피해를 입었을까요?', '「이순신 덕분」으로만 끝나는 경우 — 수군·의병·명군 셋이 함께 이겨 냈음을 짚기', 6) }, ['t_l7_3', 't_l7_4']),
    S(7, '전개', 'concept', { fig: { k: 'chain', items: [{ emoji: '🐎', name: '여진 → 청' }, { emoji: '📜', name: '신하가 되라' }, { emoji: '✋', name: '조선의 거절' }, { emoji: '🏰', name: '남한산성' }] }, title: '청의 침략 — 병자호란', content: '북쪽에서 힘을 키운 **여진**은 나라를 세우고 이름을 **청**으로 바꾼 뒤, 조선에 **임금과 신하의 관계**를 맺자고 했어요. 조선이 이를 거절하자 청이 쳐들어왔어요. 이 전쟁이 **병자호란**이에요. **인조**는 **남한산성**으로 피했지만 곧 청군에게 둘러싸였어요.', tnote: TN('청의 요구를 들은 조선 사람들은 어떤 생각을 했을까요?', '청군에게 둘러싸인 남한산성 안 사람들은 어떤 어려움을 겪었을까요?', '「청이 나빴다」로만 끝나는 경우 — 세종 때 몰아냈던 여진이 임금 노릇을 하려 하자 조선 사람들이 받아들이기 어려웠던 까닭 잇기', 5) }, ['t_l7_5', 'v_l7_1']),
    S(8, '전개', 'misconception', { title: '헷갈리기 쉬운 생각', label: '자주 하는 생각', wrong: '조선은 명과 무역으로 교류하면서 필요할 때는 무력을 쓰는 정책을 폈다', right: '명과는 좋은 관계를 이어 가고, 일본·여진과는 무역으로 교류하면서 필요할 때 무력을 썼다', hint: '조선은 명에 **사신**을 보내 문물을 받아들였어요. 무역을 하다가 국경을 넘어오면 군대를 보내 싸운 것은 **일본**과 **여진**이에요.', tnote: TN('명과 일본·여진을 대한 방법은 어떻게 달랐나요?', '쓰시마섬과 4군 6진은 어느 나라와 관련이 있나요?', '주변 나라를 모두 같은 방법으로 대했다고 보는 경우 — 나라마다 「사이좋게 / 교류와 무력」으로 나누어 말하기', 3) }, ['x_l7_1']),
    S(9, '기본문제', 'basic_problem', { title: '기본 문제 ①', scenario: { icon: '🏔️', body: '국경을 넘어와 조선 사람들의 식량과 재산을 빼앗는 일이 잦자, 세종은 북쪽으로 여진을 몰아내고 압록강 유역과 두만강 유역에 새로 땅을 지킬 곳을 두었어요.' }, question: '이렇게 넓힌 영토를 무엇이라고 하나요?', options: [{ text: '쓰시마섬' }, { text: '4군 6진', correct: true }, { text: '남한산성' }, { text: '한양 도성' }], note: '풀이: 압록강 유역에 4군, 두만강 유역에 6진을 두어 영토를 넓혔어요. 쓰시마섬은 왜구의 소굴이었어요. → **4군 6진**' }, ['x_l7_1']),
    S(10, '기본문제', 'basic_problem', { title: '기본 문제 ②', multi: true, scenario: { icon: '🚢', body: '조총을 앞세운 일본군에 잇달아 지면서 조선은 큰 위기를 맞았지만, 끝내 위기를 이겨 냈어요.' }, question: '임진왜란 때 조선이 위기를 이겨 내도록 힘이 된 것을 모두 고르세요.', options: [{ text: '이순신이 이끄는 수군', correct: true }, { text: '의병의 활약', correct: true }, { text: '명군의 도움', correct: true }, { text: '청군의 도움' }], note: '풀이: 이순신이 이끄는 수군과 백성이 스스로 만든 의병이 싸웠고, 명군이 도우러 왔어요. 청은 뒷날 조선에 쳐들어온 나라예요. → 정답 3개' }, ['x_l7_3']),
    S(11, '기본문제', 'basic_problem', { title: '기본 문제 ③', scenario: { icon: '🏰', body: '조선이 임금과 신하의 관계를 맺자는 요구를 거절하자, 북쪽의 나라가 쳐들어왔어요. 임금은 남한산성으로 피했어요.' }, question: '이 전쟁은 무엇일까요?', options: [{ text: '임진왜란' }, { text: '병자호란', correct: true }, { text: '쓰시마섬 공격' }], note: '풀이: 일본이 쳐들어온 전쟁은 임진왜란, 청이 쳐들어와 임금이 남한산성으로 피한 전쟁은 병자호란이에요. → **병자호란**' }, ['x_l7_2']),
    S(12, '기본문제', 'leveled_problem', { title: '수준을 골라 풀어요', levels: { 기본: { q: '조선이 명과 좋은 관계를 이어 간 까닭을 말해 봐요.', a: '명으로부터 필요한 문물을 받아들여 나라를 발전시키려고', steps: ['조선이 명에 보낸 사람을 떠올린다', '명에서 얻어 온 것을 찾는다', '「~하려고」로 말한다'] }, 도전: { q: '임진왜란 때 이순신이 이끄는 수군이 이길 수 있었던 까닭은 무엇일까요?', a: '전쟁 전부터 외적의 침입에 대비해 거북선을 만들고 식량과 무기를 준비했기 때문이에요', steps: ['전쟁이 나기 전에 한 일을 떠올린다', '배와 식량·무기 준비를 찾는다', '「~ 때문에」로 말한다'] }, 심화: { q: '의병은 누가 시키지 않았는데도 스스로 나라를 지키러 나섰어요. 유교의 가르침과 이어 그 까닭을 말해 봐요.', a: '여러 답 (예: 충성과 의리를 지켜 나라를 위해 싸우는 것이 마땅하다고 여겼기 때문이에요)', open: true } }, tnote: TN('기본에서 「무엇을 얻으려고」를 말했나요?', '도전에서 전쟁 전의 준비를 찾았나요?', '심화에서 「용감해서」로 끝나는 경우 — 지난 시간에 배운 유교의 가르침(충성)과 잇기', 5) }, ['g_l7_1']),
    S(13, '응용문제', 'offline_activity', { title: '모둠 — 남한산성 안 사람이 되어 보기', type: 'group', goal: '병자호란 때 청군에게 둘러싸인 남한산성 안 사람이 되어 그때 사람들의 생각과 마음을 짐작해 말풍선에 쓰기', steps: ['모둠에서 임금·신하·장군·병사 가운데 맡을 사람을 나눈다', '추운 겨울, 식량과 땔감과 무기가 모자란 성안 사정을 함께 읽는다', '맡은 사람이 되어 말풍선에 할 말을 쓴다', '차례로 읽고, 같은 성안에서도 생각이 왜 달랐을지 이야기한다'], solo: ['성안 사람 한 명을 골라 말풍선 두 개를 쓴다', '그 사람이 그렇게 생각한 까닭을 한 문장으로 쓴다'], materials: ['교과서 92쪽', '활동지(지도서 202쪽)', '색연필'], minutes: 10, tnote: TN('병사와 신하의 말풍선은 어떻게 달랐나요?', '유교의 가르침이 담긴 말풍선을 찾아볼까요?', '「춥다」 한마디로 끝나는 경우 — 그 사람이 걱정하는 것(나라·가족·임금)을 하나 더 넣기', 9) }, ['t_l7_6']),
    S(14, '응용문제', 'real_world', { title: '오늘 걸어 보는 남한산성', scenario: { icon: '🏞️', body: '주말에 가족과 오르는 경기도 광주의 **남한산성** — 성벽을 따라 걷는 길이 이어져 있어요.' }, content: '병자호란 때 임금이 피했던 **남한산성**은 오늘날 **세계 유산**으로 지정되어 많은 사람이 찾아요. 성벽을 걸으며 그때 성안 사람들의 마음을 떠올려 봐요.' }, ['r_l7_1']),
    S(15, '응용문제', 'advanced_problem', { title: '그날의 선택', context: '너는 남한산성 안의 신하야. 청군이 성을 둘러싸 식량과 땔감이 줄고, 추위로 병사들이 지쳐 가. 한쪽 신하들은 「임진왜란 때 도와준 명과의 의리를 저버리고 청에 항복할 수는 없다, 힘을 합쳐 끝까지 싸우자」고 하고, 다른 쪽 신하들은 「지금 군사로는 맞서기 어렵다, 청과 화해하고 뒷날을 꾀하자」고 해.', challenge: '① 명과의 의리를 지켜 끝까지 싸우자고 아뢴다 ② 청과 화해하고 뒷날을 꾀하자고 아뢴다 — 하나를 고르고 까닭을 말해 봐요.', note: '그때 실제로는: **②** 추위와 배고픔으로 버티기 어려워지자 인조는 청에 **항복**했어요. 청과 조선은 임금과 신하의 관계를 맺었고, 왕자를 비롯한 많은 백성이 청에 끌려갔어요. 조선은 명 대신 **청**의 영향을 받게 되었어요.\n→ 다음 이야기: 두 번의 큰 전쟁을 겪은 뒤, 조선 사람들의 **농사와 장사**는 어떻게 달라졌을까요?', tnote: TN('①을 고른 친구는 무엇을 가장 중요하게 여겼나요?', '②를 고른 친구는 누구를 지키려 했나요?', '「항복은 비겁하다」로만 끝나는 경우 — 두 쪽 모두 나라와 백성을 지키려 했음을 그때 사정에서 이해해 보기', 5) }, ['t_l7_7', 'q_l7_3']),
    S(16, '정리', 'exit_ticket', { title: '오늘 확인해요', items: [{ q: '세종 때 여진을 몰아내고 압록강·두만강 유역에 두어 넓힌 영토는?', a: '4군 6진' }, { q: '일본이 많은 군사로 조선을 침략한 전쟁은?', a: '임진왜란' }, { q: '청이 쳐들어와 임금이 남한산성으로 피한 전쟁은?', a: '병자호란' }], self: ['오늘 배운 것을 혼자 설명할 수 있어요', '조금 헷갈려요', '다시 배우고 싶어요'] }),
    S(17, '정리', 'summary', { title: '오늘 배운 것', points: ['명과는 **좋은 관계**를 이어 가며 필요한 문물을 받아들였어요.', '일본·여진과는 **무역**으로 교류하면서 필요할 때 **무력**을 썼어요(쓰시마섬 · 4군 6진).', '**임진왜란**: 수군·의병·명군의 힘으로 위기를 이겨 냈지만 피해가 컸어요.', '**병자호란**: 청의 요구를 거절하자 청이 쳐들어왔고, 조선은 청에 항복했어요.'], arrows: ['왜구·여진의 노략질 → 쓰시마섬 공격 · 4군 6진', '일본의 침략 → 수군·의병·명군 → 위기를 이겨 냄', '청의 요구를 거절 → 병자호란 → 항복 → 청의 영향', '다음: 전쟁 뒤 조선의 농사와 장사는 어떻게 달라졌을까?'] }, ['g_l7_2']),
    S(18, '정리', 'self_assessment', { title: '얼마나 잘했을까 — 주제 마무리', items: ['📚 지식·이해 — 유교 문화가 조선 사람들의 생각과 생활에 미친 영향을 설명할 수 있어요', '🔧 과정·기능 — 유교 문화에 따라 달라진 생각과 생활을 여러 분야에서 조사할 수 있어요', '💛 가치·태도 — 조선 시대 사람들의 생활 모습에 관심과 흥미를 갖게 되었어요'], prompts: ['별 두 개 이하인 칸은 지난 시간들의 「오늘 배운 것」을 다시 펼쳐 봐요.'] }, ['g_l7_2']),
    S(19, '정리', 'next_lesson', { title: '다음 시간엔', preview: '다음 시간에는 새 주제를 열고 **조선 후기의 경제적 변화**를 알아볼 거예요. 전쟁 뒤 조선 사람들의 농사와 장사는 어떻게 달라졌을까요?', emoji: '🌾' }, ['c_l7_1'])
